#include<bits/stdc++.h>

using namespace std;

class PhanSo {
	private:
		int tuSo; 
		int mauSo;
	public:
		PhanSo(int tu = 0, int mau = 1) {
		    tuSo = tu;
		    mauSo = mau;
		}
	    friend istream& operator >>(istream &is, PhanSo &ps) {
	        cout << "\nNhap phan so: ";
	        is >> ps.tuSo >> ps.mauSo;
	        return is;
	    }
		friend ostream& operator <<(ostream &os, const PhanSo &ps) {
		    os << ps.tuSo << "/" << ps.mauSo;
		    return os;
		}
		void rutGon() {
	        // 1. Tìm ước chung lớn nhất (UCLN) của tử và mẫu
	        int ucln = gcd(tuSo, mauSo); 
	        // 2. Chia cả tử và mẫu cho UCLN
	        tuSo /= ucln;
	        mauSo /= ucln;
	        // 3. Chuẩn hóa dấu (đảm bảo mẫu số luôn dương)
	        if (mauSo < 0) {
	            tuSo = -tuSo;
	            mauSo = -mauSo;
	        }
	    }
	    bool operator ==(const PhanSo& ps) const {
		    return (this->tuSo * ps.mauSo == this->mauSo * ps.tuSo);
		}
};

// Hàm này đặt bên ngoài, phía dưới Class PhanSo
void soSanh(const PhanSo& ps1, const PhanSo& ps2) {
    // Gọi toán tử == để lấy kết quả so sánh giữa ps1 và ps2
    if (ps1 == ps2) { 
        cout << "Hai phan so bang nhau.\n";
    } 
    else {
        cout << "Hai phan so khong bang nhau.\n";
    }
}

int main(){
	PhanSo ps1(10, 12); // Định nghĩa và gán giá trị ngay từ đầu
	PhanSo ps2; 
    cout << "--- Nhap phan so ps2 ---\n";
    cin >> ps2; 
    cout << "ps1 = " << ps1 << endl;
    cout << "ps2 = " << ps2 << endl;
    cout << "\n--- Ket qua so sanh ---\n";
    soSanh(ps1, ps2); 
}

